"""Synchronize mutable architecture indexes; never rewrites historical packages."""
from pathlib import Path
import json,os
R=Path(__file__).resolve().parents[2];E=R/'docs/execution/evidence/arch-09-async-2026-10-09'

def main():
    files=json.loads((R/'docs/execution/evidence/arch-08-domain-2026-10-09/current-documents.json').read_text(encoding='utf-8'))['files']
    files+=['docs/architecture/android-collector.md','docs/requirements/context-model.md','docs/product/ai-agent-specification.md']
    protected=json.loads((E/'preservation-before.json').read_text(encoding='utf-8'))['files']
    assert not set(files)&set(protected)
    def link(p,target):return os.path.relpath(R/target,p.parent).replace('\\','/')
    sections={
      'docs/architecture/high-level-design.md':('Async HLD','Một PostgreSQL J2 dispatch authority; user/API accept atomic domain+enqueue, workers profiles riêng thi hành typed tickets. Native upload→durable receipt→worker effect/Review→typed client sync; daily/manual prices freeze input và quota, Agent continuation và forecast checkpoint không tạo financial authority thứ hai.'),
      'docs/architecture/low-level-design.md':('Async LLD','Claim workspace access/recovery anchor trước job lock; DB wall-clock sau lock, live ticket và bounded heartbeat/deadline. Effect+processed/history/replay atomic, queue ACK sau domain commit; retry floor/cycles không reset counters. Native ACK pairing/dedupe/restore và query side-effect-free theo hồ sơ async.'),
      'docs/architecture/module-high-level-design.md':('Ownership và worker ports','SharedJobs owns policy/deadline/lease/attempts; Market owns refresh input/checkpoint, MarketQuota narrow broker owns private shared quota buckets; Planning owns forecast input/result. AgentWorker giữ cả assistant_message local port và multi-step runs, không bỏ chat cũ. Ops chỉ sanitized projections/control requests, không read private quota/coverage.'),
      'docs/architecture/tech-stack.md':('Queue/compute implementation choice','Chọn pg narrow SQL queue ports cho J2, không thêm Redis/vendor queue/library schema khác. ForecastWorker supervisor dùng bounded worker_threads pool1 cho pure compute; heartbeat/cancel/DB trên supervisor loop. Exact runtime versions/ARM64/performance chưa pin/benchmark; threads không là security sandbox.'),
      'docs/architecture/views/architecture-views.md':('V14 — Async/sync','Sơ đồ sequence/state ở hồ sơ async chỉ rõ native durable ACK khác actual posted, provider I/O ngoài transaction, live fence khi publish và cancel/finish race. Current API004153operations/634schemas và DB00587bảng/1001cột/162FK là thiết kế, không runtime.'),
      'docs/architecture/deployment-topology.md':('Scheduler và worker runtime topology','I0/I1 không đổi. Host tick60s và durable due scans chạy dù mọi clients tắt; private worker lanes theo capability, CPU pool bounded, native WorkManager chỉ uploader riêng. LISTEN/NOTIFY optional wake-up không durable queue. Quota/backup/restore gates vẫn phải đo; không provision hoặc auto paid fallback.'),
      'docs/architecture/environment-matrix.md':('Async environment gate','Local synthetic dùng fake adapters/clock để test faults; I1 conditional không có quota/availability proof. Real egress/native uploads phải qua AUTH/SEC/provider/native gates. Các timings/capacity trong registry là initial config, không SLO đã đạt.'),
      'docs/data/logical-data-model.md':('DB005 async additions','Kế thừa86bảng/988cột, thêm provider_quota_buckets10cột, jobs.policy_version/deadline_at và refresh_jobs.request_payload_id. Target87bảng/1001cột/162FK; no destructive old-column edits, payload type/request-intent/coverage snapshot guards design only. Legacy queue fields/indexes chưa cutover, không active authority.'),
      'docs/data/data-requirements.md':('Async data lifecycle','Frozen refresh selection/rights/normalization, request-intent CAS, quota windows/cooldown, queue policy/deadline và native pending/ACK replay/quarantine có bounds. Confirmed import rows pinned, coverage snapshot control-versioned, no raw/OTP/server/model/log. Erasure inventory bao gồm mới; restore không reset quota hoặc auto repost missing receipt.'),
      'docs/product/backend-backlog.md':('Implementation inputs — giữ đủ21 REQUIRED/41 AC','BE-08/09 implement intake/dedupe/atomic import; BE-06/07 prices/scheduler/quota; BE-15 Assistant/Agent budgets/continuation; BE-13/14 forecast chunk worker; BE-17 J2 SQL/fences/reaper; BE-18 security/restore/retention; BE-19 API004 adapters/coverage paging; BE-20/21 chạy32ASN cases thật. Không bỏ feature hoặc nhận documentation/model checks là DONE.'),
      'docs/product/business-rules.md':('Async refinements','Không tăng parent requirements: ACK≠posted; delivery retry không tạo actual effect lần2; equal amount/time không tự dedupe; cancellation không reverse committed facts. Source quota/rights, snapshot coverage và recovery epoch thắng completion trễ; Agent/draft/forecast không ghi actual. Money/calendar/Goal criteria theo ARCH-08 giữ nguyên.'),
      'docs/product/cost-model.md':('Async resource/cost assumptions','Không thêm queue vendor hoặc phí thuê dịch vụ do lựa chọn J2; vẫn có CPU/RAM/disk/network/backup/model/provider cost/quota phải đo theo môi trường. Daily18hVN, worker slots, largest1000trials/360months và encrypted journals chưa benchmark; free VM có điều kiện không bảo đảm đủ tải. No silent paid fallback/quota overrun.'),
      'docs/requirements/srs.md':('ASY-01…32 refinements','Giữ41parentAC/full scope. ASY làm rõ acceptance/enqueue, typed work/fence/retry, notification ACK/dedupe/offline/restore, daily/manual prices/quota, atomic import, inherited Assistant/Agent/forecast, owner sync/cursors/outcome. Các32ASN runtime cases đều NOT RUN; không gộp UI/mock/schema/model thành integrated/real PASS.'),
      'docs/security/security-design.md':('Async security binding','Base ARCH-07 policy/bundle giữ hash lịch sử. ARCH-09 addendum pin API004/DB005 và matrix153/classification87; narrow MarketQuota broker, no direct Ops finance/coverage/quota namespace read. Current consent/revoke/erase/epoch kiểm tại intake, claim và finalize. Witness restore gate và secret custody không đổi; chưa security runtime PASS.'),
      'docs/testing/integration-handover.md':('Async integration handover','Target hiện hành API004 với CSV header selector fix/completeness flags/coverage paging; prototype vẫn hybrid và consumers chưa migrate. SQL005 design/bundle/registry cần backend implementation trước integration. Pending status/query không advance jobs; ACK/enqueue khác completion.32ASN cases và AUTH/SEC/DOM/native/provider gates chưa chạy.'),
      'docs/testing/technical-spikes.md':('SPIKE-ASY-01…06 — ALL NOT RUN','(01)≥2DB connections claim/fence/reaper/revoke/commit-loss; (02)shared quotas/cooldown/scheduler catch-up/restore; (03)native count/bytes/retention/ACK/device epoch/OS kill; (04)atomic import/pins/CSV parser+coverage cursors>100records; (05)Agent cumulative budget/unknown tool result/clarification; (06)largest forecast pool/checkpoint/memory/heartbeat/cancel/ARM64. Record exact runtime/hardware/fault points; mocks không real proof.'),
      'docs/governance/artifact-register.md':('Current async artifacts','Register FW-ASYNC-J2-001, FW-J2-REGISTRY-001, API FW-API-T1-D1J2-004, DB FW-PHYS-T1-ASYNC-005, ADR-016, ASY/ASN32refinements/cases. Prior r1/r2/ARCH01…08 packs/evidence preserved. Manifest ARCH09 chỉ design revision, không backend release hoặc frontend acceptance revision.'),
      'docs/architecture/android-collector.md':('Native sync policy supersedes pending retention ambiguity','Native encrypted pending≤1000items/8MiB/7dauto-retry; quarantine thêm≤7d rồi purge normalized payload theo consent/version được hiển thị trước real activation. ACK replay riêng≤7d/1000items/8MiB; cap overflow cảnh báo/gap, no silent pending eviction. Capture/owner epochs bất biến, missing sau restore investigation, không retag/repost. ARCH-10 vẫn cần consent UX/Keystore/Room/OS/OEM/APK tests.'),
      'docs/requirements/context-model.md':('Notification/price/Plan–Goals async context','Android listener/outbox→device API durable receipt→IngestionWorker→sealed Ledger hoặc Review; owner web/mobile đọc typed status/projection. Host scheduler→MarketWorker→approved provider→fenced observations; shared quota trước network. Assistant/Agent và ForecastWorker chỉ read/simulate/draft/results, owner confirm Plan/Goals riêng, không actual. Ops safe-control mapping không finance access.'),
      'docs/product/ai-agent-specification.md':('Execution detail — kế thừa toàn bộ AI-FR/AI-NFR','Chat/Q&A/history/mascot vẫn có assistant_message job/local port; multi-step Agent giữ cùng conversation. Awaiting_user release lease, answer CAS creates step, 8tools/60sactive/2clarifications cộng dồn qua retries/continuations. Reserve before model/tool egress, unknown charge, deterministic draft tool result lookup; no actual/owner-confirm authority. Provider/model/evals ở ARCH-12, chưa chạy thật.')}
    for name in files:
      p=R/name;s=p.read_text(encoding='utf-8')
      if '> **ARCH-09 hiện hành' not in s:
        notice=f"> **ARCH-09 hiện hành — 09/10/2026:** [Async/sync]({link(p,'docs/async/README.md')}), [API004: 153 operations / 634 schemas]({link(p,'docs/contracts/v2-t1-r4/README.md')}), [DB005: 87 bảng / 1001 cột]({link(p,'docs/data/target-t1-async/README.md')}) và [bundle/hashes]({link(p,'docs/async/implementation-bundle.json')}). Kế thừa đầy đủ tính năng; sửa CSV selectors và coverage paging, chốt J2/retry/ACK/scheduler/quota/cancellation/offline. **Thiết kế đã chốt; backend/SQL/native/provider/concurrency NOT RUN.** Các notes ARCH-05…08 bên dưới là lịch sử revision; target hiện hành theo004/005 và addenda này.\n\n"
        s=notice+s
      if name in sections and '## ARCH-09 — ' not in s:
        title,body=sections[name]
        s+=f"\n## ARCH-09 — {title}\n\n{body}\n\n[Hồ sơ async]({link(p,'docs/async/README.md')}), [API004]({link(p,'docs/contracts/v2-t1-r4/README.md')}), [DB005]({link(p,'docs/data/target-t1-async/README.md')}), [ADR-016]({link(p,'docs/architecture/adr/ADR-016-postgresql-dispatch-and-explicit-sync-outcomes.md')}), [32 ca runtime]({link(p,'docs/async/acceptance-plan.md')}).\n"
      if name=='docs/architecture/architecture-decision-agenda.md':
        s=s.replace('ARCH-09…13 REVIEW PENDING','ARCH-09 ACCEPTED ASYNC/SYNC DESIGN; ARCH-10…13 REVIEW PENDING')
        lines=s.splitlines()
        for i,line in enumerate(lines):
          if line.startswith('| ARCH-09 Async/sync |'):
            lines[i]='| ARCH-09 Async/sync — ACCEPTED DESIGN | [J2 queue/lease/fence/retry/ACK/native replay/daily/manual prices/Agent/forecast/client sync](../async/README.md); API004153operations và DB00587bảng | 32 runtime cases NOT RUN; schema/model/hash checks khác implementation; consumers chưa migrate | [ADR-016](adr/ADR-016-postgresql-dispatch-and-explicit-sync-outcomes.md), [change report](ARCH-09-change-report.md), [acceptance](../async/acceptance-plan.md) |'
        s='\n'.join(lines)+'\n'
      versions={'docs/architecture/high-level-design.md':('High-Level Design v1.0','High-Level Design v1.1'),
        'docs/architecture/low-level-design.md':('Low-Level Design v0.8','Low-Level Design v0.9'),
        'docs/architecture/tech-stack.md':('Tech Stack v1.6','Tech Stack v1.7'),
        'docs/architecture/views/architecture-views.md':('Architecture views v1.0','Architecture views v1.1')}
      if name in versions:s=s.replace(*versions[name])
      p.write_text(s,encoding='utf-8')
    (E/'current-documents.json').write_text(json.dumps({'date':'2026-10-09','files':sorted(files)},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(json.dumps({'updatedCurrentDocuments':len(files)}))

if __name__=='__main__':main()
